body:
`activeTab` is initialized from `tabs[0]?.key` before applying the `visible` filter. If the first tab is hidden (or `tabs` is empty), the controlled `Tabs` value can point to a non-rendered trigger/content (or be `undefined`). Consider initializing from `visibleTabs[0]?.key` and updating `activeTab` when `visibleTabs` changes.
```suggestion
  const visibleTabs = React.useMemo(
    () =>
      tabs.filter((tab) => {
        if (typeof tab.visible === 'boolean') return tab.visible;
        if (typeof tab.visible === 'string') {
          // Simple expression evaluation could go here
          return true;
        }
        return true;
      }),
    [tabs],
  );

  const [activeTab, setActiveTab] = React.useState<string | undefined>(
    () => visibleTabs[0]?.key,
  );

  React.useEffect(() => {
    if (!visibleTabs.length) {
      setActiveTab(undefined);
      return;
    }

    const isActiveVisible = visibleTabs.some((tab) => tab.key === activeTab);

    if (!isActiveVisible) {
      setActiveTab(visibleTabs[0].key);
    }
  }, [visibleTabs, activeTab]);
```
